"""Embed actual benchmark traces in a standalone browser replay; no internet required."""
from pathlib import Path
ROOT=Path(__file__).resolve().parent
T='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FRANSCUE | Simulation replay</title><style>*{box-sizing:border-box}body{font:16px system-ui,sans-serif;margin:0;background:#0b1424;color:#eaf0f8}main{max-width:1080px;margin:auto;padding:24px}h1{font-size:36px;margin:8px 0}p{color:#b4c0d1;line-height:1.5}.brand{color:#ff777b;font-weight:700;letter-spacing:2px}.panel{background:#162337;border:1px solid #31445e;border-radius:14px;padding:18px;margin:16px 0}label{display:block;margin:8px 0}select,button{font:inherit;padding:10px;border-radius:8px;background:#243b57;color:white;border:1px solid #526a87}button{cursor:pointer}input{width:100%;accent-color:#58c8ea}canvas{display:block;width:100%;height:auto;background:#101a29;border-radius:8px}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px}.metrics div{background:#0b1424;padding:12px;border-radius:8px}.metrics strong{display:block;font-size:22px;margin:5px 0}.legend{font-size:14px;color:#c7d1df}small{color:#bac5d5}</style></head><body><main><div class="brand">ST. FRANCIS SCHOOL / PHYSICAL AI</div><h1>FRANSCUE</h1><p>Recorded Bayesian search traces • synthetic BLE • controlled 2D grid</p><div class="panel"><label for="case">Choose an actual recorded benchmark case</label><select id="case"></select><label for="step">Movement step <span id="stepNo"></span></label><input id="step" type="range" min="0" max="90" value="0"><button id="play">Play replay</button> <button id="reset">Reset</button> <label><input style="width:auto" type="checkbox" id="truth"> Reveal true beacon (evaluator only)</label><canvas id="map" width="960" height="640" aria-label="Recorded rover search path and probability map"></canvas><p class="legend">Cyan: rover/path • yellow: most likely location • white outline: selected goal • grey: obstacles • red: true beacon when revealed • blue cells: posterior probability</p><div class="metrics" id="stats"></div></div><div class="panel"><h2>How to read this demo</h2><p>Perceive: synthetic RSSI reading. Decide: update cell probabilities, penalise repeat visits and plan an A* route. Act: move one grid cell. The policy never receives the true beacon coordinates. Every run lasts 90 moves; the evaluator separately measures first approach within 0.8 m. This is a replay of recorded Python model runs, not a live robot or a real-time RF simulation. Confidence is conditional on the model, not a verified probability of real-world rescue.</p></div></main><script>const data=__DATA__;
const $=id=>document.getElementById(id), c=$('map'),ctx=c.getContext('2d'),sel=$('case'),s=$('step');let timer=null;data.forEach((d,i)=>{let o=document.createElement('option');o.value=i;o.textContent=d.layout+' / '+d.condition;sel.appendChild(o)});function draw(){let d=data[+sel.value],i=+s.value,f=d.frames[i],z=40; $('stepNo').textContent=i+' / 90';ctx.fillStyle='#101a29';ctx.fillRect(0,0,c.width,c.height);function rect(p,color){ctx.fillStyle=color;ctx.fillRect(p[0]*z,(15-p[1])*z,z,z)}function point(p,color,r){ctx.fillStyle=color;ctx.beginPath();ctx.arc((p[0]+.5)*z,(15-p[1]+.5)*z,r,0,Math.PI*2);ctx.fill()}if(f.belief){let max=Math.max(...f.belief);d.free.forEach((p,j)=>rect(p,`rgba(42,130,240,${Math.sqrt(f.belief[j]/max)*.85})`))}d.blocked.forEach(p=>rect(p,'#596477'));ctx.strokeStyle='#293b50';ctx.lineWidth=1;for(let x=0;x<=24;x++){ctx.beginPath();ctx.moveTo(x*z,0);ctx.lineTo(x*z,640);ctx.stroke()}for(let y=0;y<=16;y++){ctx.beginPath();ctx.moveTo(0,y*z);ctx.lineTo(960,y*z);ctx.stroke()}ctx.strokeStyle='#58dcf2';ctx.lineWidth=4;ctx.beginPath();d.frames.slice(0,i+1).forEach((v,j)=>{let x=(v.position[0]+.5)*z,y=(15-v.position[1]+.5)*z;j?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();if(f.goal){ctx.strokeStyle='white';ctx.lineWidth=3;ctx.strokeRect(f.goal[0]*z+4,(15-f.goal[1])*z+4,z-8,z-8)}if(f.estimate)point(f.estimate,'#ffd166',10);if($('truth').checked)point(d.beacon,'#ff626d',13);point(f.position,'#58dcf2',12);let hit=$('truth').checked?(d.metrics.first_hit_step===null?'Not reached':d.metrics.first_hit_step):'Hidden';$('stats').innerHTML=[['Simulated RSSI',f.rssi+' dBm'],['Peak model belief',(f.peak*100).toFixed(1)+'%'],['Belief entropy',f.entropy],['First approach step',hit]].map(a=>`<div><small>${a[0]}</small><strong>${a[1]}</strong></div>`).join('')}
function stop(){if(timer!==null){clearInterval(timer);timer=null}$('play').textContent='Play replay'}$('play').onclick=()=>{if(timer!==null){stop();return}if(+s.value===90)s.value=0;$('play').textContent='Pause';timer=setInterval(()=>{s.value=+s.value+1;draw();if(+s.value===90)stop()},160)};$('reset').onclick=()=>{stop();s.value=0;draw()};sel.onchange=()=>{stop();s.value=0;draw()};s.oninput=draw;$('truth').onchange=draw;draw();</script></body></html>'''
(ROOT/'replay.html').write_text(T.replace('__DATA__',(ROOT/'evidence/replays.json').read_text()),encoding='utf-8')
